// Initialize DSU structure for n vertices (0-indexed)
void dsu_init(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

// Find with path compression
int dsu_find(int x) {
    if (parent[x] != x) {
        parent[x] = dsu_find(parent[x]);
    }
    return parent[x];
}

// Union by rank
void dsu_union(int x, int y) {
    int rx = dsu_find(x);
    int ry = dsu_find(y);
    if (rx == ry) return;
    if (rank[rx] < rank[ry]) {
        parent[rx] = ry;
    } else if (rank[rx] > rank[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rank[rx]++;
    }
}

