typedef struct {
    int *parent;
    int *size;
    int n;
} DSU;

int dsu_find(DSU *d, int x) {
    if (d->parent[x] != x)
        d->parent[x] = dsu_find(d, d->parent[x]);
    return d->parent[x];
}

void dsu_unite(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return;
    if (d->size[a] < d->size[b]) {
        int t = a;
        a = b;
        b = t;
    }
    d->parent[b] = a;
    d->size[a] += d->size[b];
}

int main(void) {
